func:
// msg.payload chega como string crua (datatype utf8 no mqtt-in), nunca como
// objeto já parseado. Parseamos aqui manualmente para nunca deixar uma
// mensagem invalida derrubar o fluxo sem resposta (saida 2 = erro).
let dados;
try {
    dados = JSON.parse(msg.payload);
} catch (erro) {
    node.warn("JSON invalido recebido em '" + msg.topic + "': " + erro.message + " | payload bruto: " + msg.payload);
    msg.payload = { nome: "Desconhecido", autorizado: false, isAdmin: false };
    return [null, msg];
}

const uid = (dados && typeof dados.uid === "string") ? dados.uid.trim() : "";
if (!uid) {
    node.warn("Mensagem MQTT sem campo 'uid' valido: " + JSON.stringify(dados));
    msg.payload = { nome: "Desconhecido", autorizado: false, isAdmin: false };
    return [null, msg];
}

msg.uid_original = uid;
msg.tipo = dados.tipo;
msg.url = "http://localhost:5000/api/acesso/" + encodeURIComponent(uid);
return [msg, null];

// Payload de resposta para o ESP32 (vai pro msg.payload, que e o que o no MQTT out publica).
// isAdmin avisa o firmware que esse uid e de um admin: a proxima leitura de
// cartao deve ir para o topico a3/cadastros (modo cadastro) em vez de a3/catraca/entrada.
const respostaParaEsp = {
    nome: msg.payload.nome || "Desconhecido",
    autorizado: msg.payload.autorizado,
    isAdmin: msg.payload.isAdmin || false
};

// Payload para registrar no banco via Flask
msg.registro = {
    uid_cartao: msg.uid_original,
    nome_funcionario: msg.payload.nome || "Desconhecido",
    tipo: msg.tipo,
    autorizado: msg.payload.autorizado
};

msg.payload = respostaParaEsp;
return msg;

msg.payload = msg.registro;
msg.headers = { "Content-Type": "application/json" };
msg.url = "http://localhost:5000/api/acesso/log";
return msg;

msg.payload = {
    nome: "Desconhecido",
    autorizado: false,
    isAdmin: false
};
return msg;

let dados;
try {
    dados = JSON.parse(msg.payload);
} catch (erro) {
    node.warn("JSON invalido recebido em '" + msg.topic + "': " + erro.message + " | payload bruto: " + msg.payload);
    return null;
}

const uid = (dados && typeof dados.uid === "string") ? dados.uid.trim() : "";
if (!uid) {
    node.warn("Mensagem MQTT sem campo 'uid' valido: " + JSON.stringify(dados));
    return null;
}

msg.payload = { uid: uid };
msg.headers = { "Content-Type": "application/json" };
msg.url = "http://localhost:5000/api/cadastros/uid-pendente";
return msg;
